//! Zeroclaw route surface plugin.
//!
//! Publishes the Antigravity-facing model and CLI routing contract through
//! `PluginSchema` so the UI can render provider/model controls from D-Bus.

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ZeroclawState {
    pub status: String,
    pub selected_provider: String,
    pub selected_model: String,
    pub transport: Value,
    pub providers: Value,
    pub router: Value,
    pub model_routes: Value,
    pub tools: Value,
    pub config_schema: Value,
    pub ui_surfaces: Value,
    pub structured_output: Value,
}

pub struct ZeroclawPlugin;

impl Default for ZeroclawPlugin {
    fn default() -> Self {
        Self
    }
}

impl ZeroclawPlugin {
    pub fn new() -> Self {
        Self
    }

    fn env_or(key: &str, fallback: &str) -> String {
        std::env::var(key).unwrap_or_else(|_| fallback.to_string())
    }

    pub(crate) fn current_state() -> ZeroclawState {
        // Decoupled from factory: local routing defaults to the on-box gemma4
        // via ollama. gemma4 is also the universal router (see `router` below).
        let selected_provider = Self::env_or("LLM_PROVIDER", "ollama");
        let selected_model = Self::env_or("LLM_MODEL", "gemma4");
        let router_endpoint = Self::env_or("ZEROCLAW_ROUTER_ENDPOINT", "http://localhost:11434");
        let wg_xray_target = Self::env_or("ZEROCLAW_WG_XRAY_TARGET", "wg-xray");
        let grpc_target = Self::env_or("ZEROCLAW_GRPC_TARGET", "http://10.200.0.1:50051");

        ZeroclawState {
            status: "declared".to_string(),
            selected_provider,
            selected_model,
            transport: json!({
                "dbus_object": "/opdbus/v1/plugins/zeroclaw",
                "grpc_target": grpc_target,
                "incus_container": wg_xray_target,
                "browser_surface": "gRPC-Web through op-web",
                "rest_aliases": ["/api/zeroclaw/chat", "/api/llm/chat"],
                // Canonical OSCAL/subid mapping authority — referenced, never copied.
                "policy_source": "/opdbus/v1/plugins/oscal_subid_registry",
            }),
            providers: json!([
                {"id": "factory", "route": "factory", "kind": "orchestrator", "aliases": ["default", "auto"]},
                {"id": "codex", "route": "openai-codex", "kind": "provider", "aliases": ["openai_codex", "codex"]},
                {"id": "ollama", "route": "ollama", "kind": "local", "aliases": ["gemma", "gemma4"]},
                {"id": "antigravity", "route": "antigravity", "kind": "orchestrator", "aliases": ["google.antigravity"]},
                {"id": "google", "route": "gemini", "kind": "provider", "aliases": ["gemini", "google-gemini"]},
                {"id": "opencode", "route": "custom:opencode", "kind": "cli", "aliases": []},
                {"id": "kilocode", "route": "custom:kilocode", "kind": "cli", "aliases": ["kilo-code", "kilo_code"]},
                {"id": "openrouter", "route": "openrouter", "kind": "router", "aliases": []},
                {"id": "anthropic", "route": "anthropic", "kind": "provider", "aliases": []},
                {"id": "openai", "route": "openai", "kind": "provider", "aliases": []},
                {"id": "gemini-cli", "route": "gemini-cli", "kind": "cli", "aliases": []},
                // OSCAL compliance routing: a policy-kind provider (assess, not chat).
                // `source` points at the canonical subid registry — the mapping
                // authority — instead of restating control mappings here.
                {"id": "oscal", "route": "oscal", "kind": "policy", "aliases": ["compliance", "subid", "nist"], "source": "/opdbus/v1/plugins/oscal_subid_registry"}
            ]),
            // gemma4 is the universal router: it classifies EVERY request into a
            // route/tag (provider+model, hint, candidate OSCAL subids). It only
            // emits tags — the deterministic layer (routes below, oscal registry,
            // xray) enforces them. Not just compliance routing.
            router: json!({
                "provider": "ollama",
                "model": "gemma4",
                "endpoint": router_endpoint,
                "scope": "all",
                "role": "context_aware_allocator",
                "emits": ["provider", "model", "hint", "candidate_subids", "confidence", "thinking_budget", "reasoning_effort"],
            }),
            model_routes: json!([
                {
                    "hint": "code",
                    "provider": "openrouter",
                    "upstream_provider": "openrouter",
                    "transport": "direct",
                    "model": "anthropic/claude-sonnet-4.6",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Declared route; backend availability must be projected before execution.",
                    "api_key": null
                },
                {
                    "hint": "fast",
                    "provider": "gemini",
                    "upstream_provider": "gemini",
                    "transport": "direct",
                    "model": "gemini-2.5-flash",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Declared route; backend availability must be projected before execution.",
                    "api_key": null
                },
                {
                    "hint": "local",
                    "provider": "ollama",
                    "upstream_provider": "ollama",
                    "transport": "loopback",
                    "model": "gemma4",
                    "kind": "router",
                    "status": "declared",
                    "available": false,
                    "status_reason": "gemma4 is the declared local classifier; unavailable until Ollama projects it.",
                    "api_key": null
                },
                // Factory auto-routing: selects best available provider based on query type
                {
                    "hint": "auto",
                    "provider": "factory",
                    "upstream_provider": "factory",
                    "transport": "auto",
                    "model": "auto",
                    "kind": "orchestrator",
                    "status": "declared",
                    "available": true,
                    "status_reason": "Factory auto-router available - selects best provider based on query classification.",
                    "api_key": null
                },
                {
                    "hint": "code",
                    "provider": "factory",
                    "upstream_provider": "openrouter",
                    "transport": "direct",
                    "model": "anthropic/claude-sonnet-4.6",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory code route -> openrouter/claude; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "fast",
                    "provider": "factory",
                    "upstream_provider": "gemini",
                    "transport": "direct",
                    "model": "gemini-2.5-flash",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory fast route -> gemini/flash; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "local",
                    "provider": "factory",
                    "upstream_provider": "ollama",
                    "transport": "loopback",
                    "model": "gemma4",
                    "kind": "router",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory local route -> ollama/gemma4; requires backend projection.",
                    "api_key": null
                },
                {
                    "hint": "reasoning",
                    "provider": "factory",
                    "upstream_provider": "antigravity",
                    "transport": "direct",
                    "model": "gemini-3-pro-preview",
                    "kind": "chat",
                    "status": "declared",
                    "available": false,
                    "status_reason": "Factory reasoning route; Gemma dynamically allocates thinking budget.",
                    "api_key": null
                },
                // Compliance baseline routed through the OSCAL policy provider; the
                // model id is a canonical OSCAL profile reference resolved via the
                // subid registry, not an LLM model.
                {
                    "hint": "compliance",
                    "provider": "oscal",
                    "upstream_provider": "oscal",
                    "transport": "dbus",
                    "model": "NIST_SP_800-53_Rev5",
                    "kind": "policy",
                    "status": "declared",
                    "available": false,
                    "status_reason": "OSCAL policy provider is declared; unavailable until oscal_subid_registry is projected.",
                    "source": "/opdbus/v1/plugins/oscal_subid_registry",
                    "api_key": null
                }
            ]),
            tools: json!([
                {
                    "name": "zeroclaw.chat",
                    "description": "Send an Antigravity/Zeroclaw chat turn and return structured JSON when response_schema is present.",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "message": {"type": "string"},
                            "provider": {"type": "string"},
                            "model": {"type": "string"},
                            "response_schema": {"type": "object"}
                        },
                        "required": ["message"]
                    }
                },
                {
                    "name": "zeroclaw.models.list",
                    "description": "List cached or live models for a Zeroclaw provider.",
                    "parameters": {
                        "type": "object",
                        "properties": {"provider": {"type": "string"}},
                        "required": []
                    }
                }
            ]),
            config_schema: json!({
                "source": "zeroclaw config schema",
                "schema_crate": "schemars",
                "native_type": "zeroclaw::config::schema::Config",
                "status": "available_via_cli_or_gateway"
            }),
            ui_surfaces: json!([
                {"path": "/chat", "name": "Antigravity Chat", "schema": "zeroclaw"},
                {"path": "/grpc", "name": "gRPC Diagnostics", "schema": "plugin-service"},
                {"path": "/models", "name": "Routable Models", "schema": "zeroclaw.providers"}
            ]),
            structured_output: json!({
                "sdk": "google.antigravity",
                "config_object": "LocalAgentConfig(response_schema=UiResponseSchema)",
                "extractor": "response.structured_output()",
                "response_schema": {
                    "action": "",
                    "metadata": {},
                    "confidence_score": 0.0
                },
                "pydantic_source": [
                    "import pydantic",
                    "class UiResponseSchema(pydantic.BaseModel):",
                    "    action: str",
                    "    metadata: dict[str, str]",
                    "    confidence_score: float"
                ],
                "ui_renderer": "JsonRenderer",
                "required": true
            }),
        }
    }
}

#[async_trait]
impl StatePlugin for ZeroclawPlugin {
    fn name(&self) -> &str {
        "zeroclaw"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        Some(super::plugin_schema_defs::zeroclaw_plugin_schema())
    }

    async fn query_current_state(&self) -> Result<Value> {
        Ok(simd_json::serde::to_owned_value(Self::current_state())?)
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: "schema-declared".to_string(),
                desired_hash: "schema-declared".to_string(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(Self::current_state())?,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

//! Factory Droid agent platform plugin.
//!
//! Publishes the full Factory Public API surface (computers, sessions, models,
//! autonomy controls, token tracking) through PluginSchema so the UI can
//! render Factory configuration, session controls, and model selection from
//! the D-Bus projection.

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FactoryState {
    pub status: String,
    pub endpoint: String,
    pub auth_method: String,
    pub computers: Value,
    pub sessions: Value,
    pub session_settings: Value,
    pub models: Value,
    pub providers: Value,
    pub tools: Value,
    pub config_schema: Value,
    pub ui_surfaces: Value,
}

pub struct FactoryPlugin;

impl Default for FactoryPlugin {
    fn default() -> Self {
        Self
    }
}

impl FactoryPlugin {
    pub fn new() -> Self {
        Self
    }
    fn env_or(key: &str, fallback: &str) -> String {
        std::env::var(key).unwrap_or_else(|_| fallback.to_string())
    }

    pub(crate) fn current_state() -> FactoryState {
        let endpoint = Self::env_or("FACTORY_API_ENDPOINT", "https://api.factory.ai/api/v0");
        let auth_method = Self::env_or("FACTORY_AUTH_METHOD", "bearer");

        FactoryState {
            status: "active".to_string(),
            endpoint,
            auth_method,
            computers: json!({
                "endpoint": "/api/v0/computers",
                "provider_types": ["byom", "e2b"],
                "statuses": ["provisioning", "active", "error"],
                "source_types": [
                    {"kind": "scratch", "description": "Empty environment"},
                    {"kind": "template", "description": "Preconfigured cloud template"},
                    {"kind": "live-computer", "description": "Clone existing computer"}
                ],
                "operations": ["create", "list", "get", "update", "delete", "refresh", "restart", "installDeps", "metrics"]
            }),
            sessions: json!({
                "endpoint": "/api/v0/sessions",
                "statuses": ["idle", "pending", "running"],
                "user_message_sources": [
                    "web", "desktop", "cli_tui", "cli_exec", "cli_acp",
                    "slack", "linear", "sessions_api", "api", "automation",
                    "readiness-remediation", "readiness-evaluation",
                    "wiki-generation", "wiki-ci-setup"
                ],
                "operations": ["create", "list", "get", "update", "delete", "interrupt"],
                "message_roles": ["user", "assistant", "tool", "system"],
                "content_block_types": ["text", "image", "thinking", "redacted_thinking", "tool_use", "tool_result", "document"],
                "visibility_modes": ["both", "llm_only", "user_only"]
            }),
            session_settings: json!({
                "interaction_modes": ["auto", "spec", "agi", "mission"],
                "autonomy_levels": ["off", "low", "medium", "high"],
                "reasoning_efforts": ["none", "dynamic", "off", "minimal", "low", "medium", "high", "xhigh", "max"],
                "api_provider_locks": [
                    "bedrock", "anthropic", "vertex_anthropic", "bedrock_anthropic",
                    "bedrock_converse", "openai", "azure_openai", "google", "xai",
                    "fireworks", "baseten", "snowflake"
                ],
                "provider_locks": [
                    "anthropic", "openai", "generic-chat-completion-api",
                    "factory", "google", "xai", "voyage", "bedrock-converse"
                ]
            }),
            models: json!({
                "catalog": [
                    {"id": "claude-sonnet-4-6", "family": "anthropic"},
                    {"id": "claude-opus-4-6", "family": "anthropic"},
                    {"id": "claude-opus-4-7", "family": "anthropic"},
                    {"id": "claude-opus-4-8", "family": "anthropic"},
                    {"id": "gpt-5.5", "family": "openai"},
                    {"id": "gpt-5.5-pro", "family": "openai"},
                    {"id": "gpt-5.5-fast", "family": "openai"},
                    {"id": "gpt-5.4", "family": "openai"},
                    {"id": "gpt-5.4-fast", "family": "openai"},
                    {"id": "gpt-5.3-codex", "family": "openai"},
                    {"id": "gemini-2.5-pro", "family": "google"},
                    {"id": "gemini-2.5-flash", "family": "google"},
                    {"id": "gemini-3-pro-preview", "family": "google"},
                    {"id": "gemini-3.5-flash", "family": "google"},
                    {"id": "deepseek-v4-pro", "family": "deepseek"},
                    {"id": "glm-4.7", "family": "zhipu"},
                    {"id": "glm-5", "family": "zhipu"},
                    {"id": "kimi-k2.5", "family": "moonshot"},
                    {"id": "minimax-m2.7", "family": "minimax"},
                    {"id": "aspen-05-15", "family": "factory-internal"},
                    {"id": "almond-05-27", "family": "factory-internal"}
                ],
                "model_routes": [
                    {"hint": "best", "provider": "factory", "model": "auto", "kind": "orchestrator", "available": true, "status_reason": "Factory auto-selects best model"},
                    {"hint": "code", "provider": "factory", "model": "claude-sonnet-4-6", "kind": "chat", "available": true, "status_reason": "Claude Sonnet 4.6 via Factory"},
                    {"hint": "code", "provider": "factory", "model": "claude-opus-4-6", "kind": "chat", "available": true, "status_reason": "Claude Opus 4.6 via Factory"},
                    {"hint": "code", "provider": "factory", "model": "gpt-5.5", "kind": "chat", "available": true, "status_reason": "GPT 5.5 via Factory"},
                    {"hint": "code", "provider": "factory", "model": "gpt-5.5-pro", "kind": "chat", "available": true, "status_reason": "GPT 5.5 Pro via Factory"},
                    {"hint": "code", "provider": "factory", "model": "gemini-2.5-pro", "kind": "chat", "available": true, "status_reason": "Gemini 2.5 Pro via Factory"},
                    {"hint": "fast", "provider": "factory", "model": "gemini-2.5-flash", "kind": "chat", "available": true, "status_reason": "Gemini 2.5 Flash via Factory"},
                    {"hint": "fast", "provider": "factory", "model": "gpt-5.5-fast", "kind": "chat", "available": true, "status_reason": "GPT 5.5 Fast via Factory"},
                    {"hint": "code", "provider": "factory", "model": "deepseek-v4-pro", "kind": "chat", "available": true, "status_reason": "DeepSeek V4 Pro via Factory"}
                ]
            }),
            providers: json!([{
                "id": "factory", "route": "factory", "kind": "orchestrator",
                "aliases": ["default", "auto", "droid"],
                "endpoint": "https://api.factory.ai/api/v0", "auth": "bearer"
            }]),
            tools: json!([
                {"name": "factory.session.create", "description": "Create a Factory Droid coding session", "parameters": {"type": "object", "properties": {"computerId": {"type": "string"}, "sessionSettings": {"type": "object"}}, "required": ["computerId"]}},
                {"name": "factory.session.send", "description": "Send a message to a Factory session", "parameters": {"type": "object", "properties": {"sessionId": {"type": "string"}, "text": {"type": "string"}}, "required": ["sessionId", "text"]}},
                {"name": "factory.session.list", "description": "List active Factory sessions", "parameters": {"type": "object", "properties": {"computerId": {"type": "string"}}, "required": []}},
                {"name": "factory.computer.create", "description": "Create a Factory computer environment", "parameters": {"type": "object", "properties": {"name": {"type": "string"}, "provider": {"type": "string", "enum": ["byom", "e2b"]}}, "required": ["name"]}},
                {"name": "factory.models.list", "description": "List available models through Factory", "parameters": {"type": "object", "properties": {"family": {"type": "string"}}, "required": []}}
            ]),
            config_schema: json!({
                "source": "factory public api v0",
                "openapi_url": "https://api.factory.ai/api/v0/openapi.json",
                "api_version": "0.1.0"
            }),
            ui_surfaces: json!([
                {"path": "/factory", "name": "Factory Droid", "schema": "factory"},
                {"path": "/factory/sessions", "name": "Sessions", "schema": "factory.sessions"},
                {"path": "/factory/models", "name": "Models", "schema": "factory.models"}
            ]),
        }
    }
}

#[async_trait]
impl StatePlugin for FactoryPlugin {
    fn name(&self) -> &str {
        "factory"
    }
    fn version(&self) -> &str {
        "1.0.0"
    }
    fn schema(&self) -> Option<PluginSchema> {
        Some(super::plugin_schema_defs::factory_plugin_schema())
    }
    async fn query_current_state(&self) -> Result<Value> {
        Ok(simd_json::serde::to_owned_value(Self::current_state())?)
    }
    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: "schema-declared".to_string(),
                desired_hash: "schema-declared".to_string(),
            },
        })
    }
    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }
    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }
    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(Self::current_state())?,
            backend_checkpoint: None,
        })
    }
    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }
    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

/// Lazy-loading model manager for transformer embeddings
#[cfg(feature = "ml")]
use anyhow::Context;
use anyhow::Result;
use std::sync::Arc;

#[cfg(feature = "ml")]
use once_cell::sync::OnceCell;

use super::config::{VectorizationConfig, VectorizationLevel};
#[cfg(feature = "ml")]
use super::downloader::ModelDownloader;
#[cfg(feature = "ml")]
use super::embedder::TextEmbedder;

/// Global model manager singleton
#[cfg(feature = "ml")]
static MODEL_MANAGER: OnceCell<Arc<ModelManager>> = OnceCell::new();

/// Model manager with lazy loading
pub struct ModelManager {
    config: VectorizationConfig,
    #[cfg(feature = "ml")]
    embedder: OnceCell<TextEmbedder>,
}

impl ModelManager {
    /// Create new model manager
    pub fn new(config: VectorizationConfig) -> Self {
        Self {
            config,
            #[cfg(feature = "ml")]
            embedder: OnceCell::new(),
        }
    }

    /// Get or initialize global instance
    #[cfg(feature = "ml")]
    pub fn global() -> Arc<Self> {
        MODEL_MANAGER
            .get_or_init(|| {
                let config = VectorizationConfig::from_env();
                log::info!(
                    "Initializing global model manager with level: {}",
                    config.level
                );
                Arc::new(Self::new(config))
            })
            .clone()
    }

    /// Get or initialize global instance (stub for non-ml)
    #[cfg(not(feature = "ml"))]
    pub fn global() -> Arc<Self> {
        Arc::new(Self::new(VectorizationConfig::default()))
    }

    /// Check if vectorization is enabled
    pub fn is_enabled(&self) -> bool {
        self.config.is_enabled()
    }

    /// Get vectorization level
    #[allow(dead_code)]
    pub fn level(&self) -> VectorizationLevel {
        self.config.level
    }

    /// Embed text into vector (lazy loads model on first call)
    #[cfg(feature = "ml")]
    pub fn embed(&self, text: &str) -> Result<Vec<f32>> {
        if !self.is_enabled() {
            return Ok(Vec::new());
        }

        let embedder = self.get_or_load_embedder()?;
        embedder.embed(text)
    }

    /// Embed text (stub for non-ml)
    #[cfg(not(feature = "ml"))]
    pub fn embed(&self, _text: &str) -> Result<Vec<f32>> {
        if self.is_enabled() {
            Err(anyhow::anyhow!(
                "ML feature not enabled. Rebuild with --features ml"
            ))
        } else {
            Ok(Vec::new())
        }
    }

    /// Embed batch of texts
    #[cfg(feature = "ml")]
    #[allow(dead_code)]
    pub fn embed_batch(&self, texts: &[&str]) -> Result<Vec<Vec<f32>>> {
        if !self.is_enabled() {
            return Ok(vec![Vec::new(); texts.len()]);
        }

        let embedder = self.get_or_load_embedder()?;
        embedder.embed_batch(texts)
    }

    /// Embed batch (stub for non-ml)
    #[cfg(not(feature = "ml"))]
    #[allow(dead_code)]
    pub fn embed_batch(&self, texts: &[&str]) -> Result<Vec<Vec<f32>>> {
        if self.is_enabled() {
            Err(anyhow::anyhow!(
                "ML feature not enabled. Rebuild with --features ml"
            ))
        } else {
            Ok(vec![Vec::new(); texts.len()])
        }
    }

    /// Get or load embedder (lazy initialization)
    #[cfg(feature = "ml")]
    fn get_or_load_embedder(&self) -> Result<&TextEmbedder> {
        self.embedder.get_or_try_init(|| {
            log::info!("Loading {} model on-demand...", self.config.level);

            // Use async runtime to download if needed
            let model_dir = tokio::runtime::Handle::current()
                .block_on(async { self.ensure_model_downloaded().await })?;

            // Try to load model
            match TextEmbedder::load(&model_dir, &self.config) {
                Ok(embedder) => {
                    log::info!("Successfully loaded {} model", self.config.level);
                    Ok(embedder)
                }
                Err(e) => {
                    log::warn!("Failed to load {} model: {}", self.config.level, e);
                    // Try to fall back to lower level
                    self.try_fallback_model().or(Err(e))
                }
            }
        })
    }

    /// Ensure model is downloaded, download if missing
    #[cfg(feature = "ml")]
    async fn ensure_model_downloaded(&self) -> Result<std::path::PathBuf> {
        let model_dir = self.get_model_path()?;

        // Check if model already exists
        let model_file = model_dir.join("model.onnx");
        let tokenizer_file = model_dir.join("tokenizer.json");

        if model_file.exists() && tokenizer_file.exists() {
            log::info!("Model already available at {:?}", model_dir);
            return Ok(model_dir);
        }

        // Model missing, download it
        log::info!("Model not found locally, downloading from Hugging Face...");

        let downloader = ModelDownloader::new(&self.config.model_dir)
            .context("Failed to initialize model downloader")?;

        downloader
            .ensure_model_available(self.config.level)
            .await
            .context("Failed to download model from Hugging Face")
    }

    /// Try to load a fallback model at lower level
    #[cfg(feature = "ml")]
    fn try_fallback_model(&self) -> Result<TextEmbedder> {
        let fallback_level = match self.config.level {
            VectorizationLevel::High => VectorizationLevel::Medium,
            VectorizationLevel::Medium => VectorizationLevel::Low,
            _ => {
                return Err(anyhow::anyhow!(
                    "No fallback available for level {:?}",
                    self.config.level
                ))
            }
        };

        log::warn!("Falling back to {} level", fallback_level);

        let model_dir = self.get_model_path_for_level(fallback_level)?;

        // Create fallback config with same execution provider
        let mut fallback_config = self.config.clone();
        fallback_config.level = fallback_level;

        TextEmbedder::load(&model_dir, &fallback_config)
            .context(format!("Fallback to {} failed", fallback_level))
    }

    /// Get model directory path for current level
    #[allow(dead_code)]
    fn get_model_path(&self) -> Result<std::path::PathBuf> {
        self.get_model_path_for_level(self.config.level)
    }

    /// Get model directory path for specific level
    #[allow(dead_code)]
    fn get_model_path_for_level(&self, level: VectorizationLevel) -> Result<std::path::PathBuf> {
        let model_name = level
            .model_name()
            .ok_or_else(|| anyhow::anyhow!("No model for level {:?}", level))?;

        // Convert model name to directory name
        // e.g., "sentence-transformers/paraphrase-MiniLM-L6-v2" -> "paraphrase-MiniLM-L6-v2"
        let dir_name = model_name.split('/').next_back().unwrap_or(model_name);

        Ok(self.config.model_dir.join(dir_name))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_model_path_generation() {
        let config = VectorizationConfig {
            level: VectorizationLevel::Medium,
            ..Default::default()
        };

        let manager = ModelManager::new(config);
        let path = manager.get_model_path().unwrap();

        assert!(path.to_string_lossy().contains("paraphrase-MiniLM-L6-v2"));
    }

    #[test]
    fn test_disabled_vectorization() {
        let config = VectorizationConfig {
            level: VectorizationLevel::None,
            ..Default::default()
        };

        let manager = ModelManager::new(config);
        assert!(!manager.is_enabled());

        let result = manager.embed("test");
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Vec::<f32>::new());
    }
}

//! Plugin schema catalog and compatibility helpers.
//!
//! Architectural rule:
//! - plugin code is the source of schema truth
//! - that schema is also the footprint and JSON render contract
//! - this module stores indexed copies of that schema for validation/export
//!
//! Compatibility note:
//! a large amount of built-in schema data still lives in this file. Those
//! built-ins are intentionally exposed through explicit compatibility helpers
//! so runtime code can continue to resolve legacy schemas without turning this
//! catalog back into a second schema authority.

use serde::{Deserialize, Serialize};
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

/// Default JSON Schema dialect (can be overridden per-schema)
pub const DEFAULT_SCHEMA_DIALECT: &str = "https://json-schema.org/v1/2026";

/// Known dialect identifiers
pub mod dialects {
    pub const DRAFT_07: &str = "http://json-schema.org/draft-07/schema#";
    pub const V2026: &str = "https://json-schema.org/v1/2026";
}

/// Path to the json-schema-spec repository relative to workspace root
const SCHEMA_SPEC_PATH: &str = "json-schema-spec";

/// Schema field type
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum FieldType {
    String,
    Integer,
    Float,
    Boolean,
    Array(Box<FieldType>),
    Object(HashMap<String, FieldSchema>),
    Enum(Vec<String>),
    Any,
}

/// Schema for a single field
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct FieldSchema {
    /// Field type
    pub field_type: FieldType,
    /// Whether the field is required
    #[serde(default)]
    pub required: bool,
    /// Description of the field
    #[serde(default)]
    pub description: String,
    /// Default value if not provided
    #[serde(default)]
    pub default: Option<Value>,
    /// Example value for documentation
    #[serde(default)]
    pub example: Option<Value>,
    /// Validation constraints
    #[serde(default)]
    pub constraints: Vec<Constraint>,
    /// Unconditional readOnly - field cannot be modified
    #[serde(default)]
    pub read_only: bool,
    /// Conditional readOnly via propertyDependencies
    #[serde(default)]
    pub read_only_when: Option<ReadOnlyCondition>,
}

/// Condition for conditional readOnly (via propertyDependencies)
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ReadOnlyCondition {
    /// The property to check (e.g., "status", "running")
    pub property: String,
    /// The value that triggers readOnly (e.g., "locked", "true")
    pub value: String,
}

/// Validation constraint
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Constraint {
    /// Minimum value (for numbers) or length (for strings/arrays)
    Min { value: f64 },
    /// Maximum value (for numbers) or length (for strings/arrays)
    Max { value: f64 },
    /// Regex pattern (for strings)
    Pattern { regex: String },
    /// Value must be one of these
    OneOf { values: Vec<Value> },
    /// Reference to another field that must exist
    RequiresField { field: String },
    /// Custom validation function name
    Custom { validator: String },
}

/// Plugin schema definition
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PluginSchema {
    /// Plugin name
    pub name: String,
    /// Logical category used by the registry, renderer, and compliance overlays
    #[serde(default = "default_category")]
    pub category: String,
    /// Schema version
    pub version: String,
    /// Description
    pub description: String,
    /// Fields in the plugin state
    pub fields: HashMap<String, FieldSchema>,
    /// Dependencies on other plugins
    #[serde(default)]
    pub dependencies: Vec<String>,
    /// Example state for documentation
    #[serde(default)]
    pub example: Option<Value>,
    /// Paths that are always readOnly (e.g., ["/id", "/metadata"])
    #[serde(default)]
    pub immutable_paths: Vec<String>,
    /// Schema tags (e.g., ["immutable"] for fully immutable schemas)
    #[serde(default)]
    pub tags: Vec<String>,
    /// JSON Schema dialect to use (defaults to DEFAULT_SCHEMA_DIALECT)
    #[serde(default = "default_dialect")]
    pub dialect: String,
    /// Mutation index for the identity sled
    #[serde(default)]
    pub mutation_index: Option<u64>,
}

fn default_dialect() -> String {
    DEFAULT_SCHEMA_DIALECT.to_string()
}

fn default_category() -> String {
    "uncategorized".to_string()
}

impl PluginSchema {
    /// Check if the schema state is valid (for the identity sled)
    pub fn is_valid(&self) -> bool {
        !self.name.is_empty() && !self.version.is_empty()
    }

    /// Create a new plugin schema builder
    pub fn builder(name: &str) -> PluginSchemaBuilder {
        PluginSchemaBuilder::new(name)
    }

    /// Validate a state value against this schema
    pub fn validate(&self, state: &Value) -> ValidationResult {
        let mut errors = Vec::new();
        let mut warnings = Vec::new();

        // Check required fields
        for (field_name, field_schema) in &self.fields {
            if field_schema.required && state.get(field_name).is_none() {
                errors.push(format!("Missing required field: {}", field_name));
            }
        }

        // Validate present fields
        if let Some(obj) = state.as_object() {
            for (field_name, field_value) in obj {
                if let Some(field_schema) = self.fields.get(field_name) {
                    if let Err(e) = validate_field(field_name, field_value, field_schema) {
                        errors.push(e);
                    }
                } else {
                    warnings.push(format!("Unknown field: {}", field_name));
                }
            }
        }

        ValidationResult {
            valid: errors.is_empty(),
            errors,
            warnings,
        }
    }

    /// Generate a template state with default values
    pub fn generate_template(&self) -> Value {
        let mut template = simd_json::value::owned::Object::new();

        for (field_name, field_schema) in &self.fields {
            let value = if let Some(default) = &field_schema.default {
                default.clone()
            } else if let Some(example) = &field_schema.example {
                example.clone()
            } else {
                default_for_type(&field_schema.field_type)
            };
            template.insert(field_name.clone(), value);
        }

        Value::Object(Box::new(template))
    }

    /// Convert to JSON Schema 2026 format (default)
    ///
    /// Includes support for:
    /// - `readOnly` on individual fields
    /// - `propertyDependencies` for conditional immutability
    /// - Schema-level immutability via tags
    pub fn to_json_schema(&self) -> Value {
        let is_fully_immutable = self.tags.contains(&"immutable".to_string());
        let mut properties = simd_json::value::owned::Object::new();
        let mut required = Vec::new();
        let mut property_dependencies: HashMap<String, HashMap<String, Vec<String>>> =
            HashMap::new();

        for (field_name, field_schema) in &self.fields {
            let mut field_json = field_type_to_json_schema_2026(&field_schema.field_type);

            // Add description if present
            if !field_schema.description.is_empty() {
                if let Some(obj) = field_json.as_object_mut() {
                    obj.insert("description".to_string(), json!(field_schema.description));
                }
            }

            // Add readOnly if field is unconditionally immutable, in immutable_paths, or schema is fully immutable
            let path = format!("/{}", field_name);
            if field_schema.read_only || self.immutable_paths.contains(&path) || is_fully_immutable
            {
                if let Some(obj) = field_json.as_object_mut() {
                    obj.insert("readOnly".to_string(), json!(true));
                }
            }

            // Collect propertyDependencies for conditional readOnly
            if let Some(condition) = &field_schema.read_only_when {
                property_dependencies
                    .entry(condition.property.clone())
                    .or_default()
                    .entry(condition.value.clone())
                    .or_default()
                    .push(field_name.clone());
            }

            properties.insert(field_name.clone(), field_json);
            if field_schema.required {
                required.push(Value::String(field_name.clone()));
            }
        }

        let mut schema = json!({
            "$schema": &self.dialect,
            "title": self.name,
            "description": self.description,
            "x-plugin-category": self.category,
            "type": "object",
            "properties": properties,
            "required": required
        });

        // Add propertyDependencies if any conditional readOnly fields exist
        if !property_dependencies.is_empty() {
            let mut deps_json = simd_json::value::owned::Object::new();
            for (prop, value_map) in property_dependencies {
                let mut values_json = simd_json::value::owned::Object::new();
                for (value, fields) in value_map {
                    let mut props = simd_json::value::owned::Object::new();
                    for field in fields {
                        props.insert(field, json!({"readOnly": true}));
                    }
                    values_json.insert(
                        value,
                        json!({
                            "properties": props
                        }),
                    );
                }
                deps_json.insert(prop, Value::Object(Box::new(values_json)));
            }
            if let Some(obj) = schema.as_object_mut() {
                obj.insert(
                    "propertyDependencies".to_string(),
                    Value::Object(Box::new(deps_json)),
                );
            }
        }

        schema
    }

    /// Convert to JSON Schema draft-07 format (deprecated, for backward compatibility)
    #[deprecated(since = "2.0.0", note = "Use to_json_schema() for JSON Schema 2026")]
    pub fn to_json_schema_draft07(&self) -> Value {
        let mut properties = simd_json::value::owned::Object::new();
        let mut required = Vec::new();

        for (field_name, field_schema) in &self.fields {
            properties.insert(
                field_name.clone(),
                field_type_to_json_schema(&field_schema.field_type),
            );
            if field_schema.required {
                required.push(Value::String(field_name.clone()));
            }
        }

        json!({
            "$schema": "http://json-schema.org/draft-07/schema#",
            "title": self.name,
            "description": self.description,
            "type": "object",
            "properties": properties,
            "required": required
        })
    }

    /// Convert to the legacy contract-style schema while using this registry
    /// entry as the only source of truth for the tunable section.
    pub fn to_contract_json_schema(&self) -> Value {
        self.to_contract_json_schema_as(&self.name)
    }

    /// Convert to the legacy contract-style schema using an alternate public
    /// plugin name for compatibility aliases such as `systemd`.
    pub fn to_contract_json_schema_as(&self, public_name: &str) -> Value {
        let mut include_paths: Vec<String> = self
            .fields
            .keys()
            .map(|field| format!("/tunable/{field}"))
            .collect();
        include_paths.sort();

        let mut secret_paths: Vec<String> = self
            .fields
            .keys()
            .filter(|field| is_secret_field_name(field))
            .map(|field| format!("/tunable/{field}"))
            .collect();
        secret_paths.sort();

        let mut pii_paths: Vec<String> = self
            .fields
            .keys()
            .filter(|field| is_pii_field_name(field))
            .map(|field| format!("/tunable/{field}"))
            .collect();
        pii_paths.sort();

        let sensitivity = if secret_paths.is_empty() {
            "internal"
        } else {
            "secret"
        };

        json!({
            "$schema": DEFAULT_SCHEMA_DIALECT,
            "$id": format!("https://op-dbus.local/schemas/plugins/{public_name}.contract.json"),
            "title": format!("{public_name} contract schema"),
            "description": self.description,
            "type": "object",
            "required": [
                "schema_version",
                "plugin",
                "object_type",
                "object_id",
                "stub",
                "immutable",
                "tunable",
                "observed",
                "meta",
                "semantic_index",
                "privacy_index"
            ],
            "properties": {
                "schema_version": {
                    "type": "string",
                    "const": self.version
                },
                "plugin": {
                    "type": "string",
                    "const": public_name
                },
                "object_type": {
                    "type": "string",
                    "const": format!("{}_object", public_name.replace('-', "_"))
                },
                "object_id": {
                    "type": "string",
                    "minLength": 1
                },
                "stub": {
                    "type": "object",
                    "required": ["system_id", "source", "source_ref", "discovered_at"],
                    "properties": {
                        "system_id": { "type": "string", "minLength": 1 },
                        "source": { "type": "string", "minLength": 1 },
                        "source_ref": { "type": "string", "minLength": 1 },
                        "discovered_at": { "type": "string", "format": "date-time" }
                    },
                    "additionalProperties": false
                },
                "immutable": {
                    "type": "object",
                    "required": ["created_at", "created_by_plugin", "identity_keys", "provider"],
                    "properties": {
                        "created_at": { "type": "string", "format": "date-time" },
                        "created_by_plugin": { "type": "string", "const": public_name },
                        "identity_keys": {
                            "type": "array",
                            "items": { "type": "string" },
                            "minItems": 1,
                            "default": ["object_id"]
                        },
                        "provider": { "type": "string", "default": "op-dbus" }
                    },
                    "additionalProperties": false
                },
                "tunable": self.to_json_schema(),
                "observed": {
                    "type": "object",
                    "required": ["last_observed_at"],
                    "properties": {
                        "last_observed_at": { "type": "string", "format": "date-time" },
                        "status": { "type": "string" },
                        "drift_detected": { "type": "boolean", "default": false },
                        "metrics": { "type": "object" }
                    },
                    "additionalProperties": true
                },
                "meta": {
                    "type": "object",
                    "required": [
                        "dependencies",
                        "include_in_recovery",
                        "recovery_priority",
                        "category",
                        "sensitivity",
                        "tags",
                        "enabled"
                    ],
                    "properties": {
                        "dependencies": {
                            "type": "array",
                            "items": { "type": "string" },
                            "default": self.dependencies
                        },
                        "include_in_recovery": { "type": "boolean", "default": true },
                        "recovery_priority": { "type": "integer", "minimum": 0, "default": 50 },
                        "category": {
                            "type": "string",
                            "default": self.category
                        },
                        "sensitivity": {
                            "type": "string",
                            "enum": ["public", "internal", "secret"],
                            "default": sensitivity
                        },
                        "tags": {
                            "type": "array",
                            "items": { "type": "string" },
                            "default": self.tags
                        },
                        "enabled": { "type": "boolean", "default": true }
                    },
                    "additionalProperties": false
                },
                "semantic_index": {
                    "type": "object",
                    "required": ["include_paths", "exclude_paths", "chunking", "redaction"],
                    "properties": {
                        "include_paths": {
                            "type": "array",
                            "items": { "type": "string" },
                            "default": include_paths
                        },
                        "exclude_paths": {
                            "type": "array",
                            "items": { "type": "string" },
                            "default": ["/stub/discovered_at"]
                        },
                        "chunking": {
                            "type": "object",
                            "required": ["strategy", "max_tokens"],
                            "properties": {
                                "strategy": { "type": "string", "enum": ["json-path-group"], "default": "json-path-group" },
                                "max_tokens": { "type": "integer", "minimum": 64, "default": 512 }
                            },
                            "additionalProperties": false
                        },
                        "redaction": {
                            "type": "object",
                            "required": ["enabled"],
                            "properties": {
                                "enabled": { "type": "boolean", "default": true }
                            },
                            "additionalProperties": false
                        }
                    },
                    "additionalProperties": false
                },
                "privacy_index": {
                    "type": "object",
                    "required": ["redaction"],
                    "properties": {
                        "redaction": {
                            "type": "object",
                            "required": [
                                "rules",
                                "default_action",
                                "secret_paths",
                                "pii_paths",
                                "hash_salt_ref",
                                "reversible"
                            ],
                            "properties": {
                                "rules": {
                                    "type": "array",
                                    "items": {
                                        "type": "object",
                                        "required": ["path", "action"],
                                        "properties": {
                                            "path": { "type": "string" },
                                            "action": { "type": "string", "enum": ["drop", "mask", "hash"] },
                                            "reason": { "type": "string" }
